{
  "base": {
    "color": {
      "2": {
        "$value": "rgba(31, 128, 255, 0.25)",
        "$type": "color"
      },
      "10": {
        "$value": "#000",
        "$type": "color"
      },
      "p3": {
        "$value": "rgba(255, 0, 0, 0.5)",
        "$type": "color"
      },
      "ok": {
        "$value": "rgba(213, 134, 121, 0.3)",
        "$type": "color"
      }
    },
    "space": {
      "calc": {
        "$value": "{space.a} * 2",
        "$type": "spacing"
      },
      "a": {
        "$value": "1.2346rem",
        "$type": "spacing"
      },
      "n": {
        "$value": "12",
        "$type": "spacing"
      }
    },
    "motion": {
      "a": {
        "$value": "250",
        "$type": "number"
      },
      "b": {
        "$value": "{motion.a}",
        "$type": "number"
      }
    },
    "text": {
      "a": {
        "$value": "strike-through",
        "$type": "textDecoration"
      },
      "b": {
        "$value": "none",
        "$type": "textCase"
      }
    },
    "type": {
      "a": {
        "$value": {
          "fontFamilies": "A, B",
          "fontSizes": "{space.n}",
          "fontWeights": "600",
          "lineHeights": "1.5rem",
          "textCase": "uppercase"
        },
        "$type": "typography"
      },
      "b": {
        "$value": {},
        "$type": "typography"
      }
    },
    "shadow": {
      "a": {
        "$value": {
          "color": "#000",
          "offsetX": "1",
          "offsetY": "2",
          "blur": "{space.n}",
          "spread": "0",
          "inset": false
        },
        "$type": "shadow"
      }
    },
    "a": {
      "b": {
        "c": {
          "$value": "1e+21",
          "$type": "number"
        }
      }
    }
  },
  "themes/2": {
    "color": {
      "x": {
        "$value": "#111",
        "$type": "color"
      }
    }
  },
  "themes/dark": {
    "color": {
      "x": {
        "$value": "#222",
        "$type": "color"
      }
    }
  },
  "$themes": [
    {
      "name": "default",
      "group": "dfw",
      "description": "dfw base tokens (design/tokens/tokens.json)",
      "isSource": false,
      "selectedTokenSets": {
        "base": "enabled"
      }
    },
    {
      "name": "2",
      "group": "dfw",
      "description": "dfw theme design/tokens/themes/2.json over the base",
      "isSource": false,
      "selectedTokenSets": {
        "base": "enabled",
        "themes/2": "enabled"
      }
    },
    {
      "name": "dark",
      "group": "dfw",
      "description": "dfw theme design/tokens/themes/dark.json over the base",
      "isSource": false,
      "selectedTokenSets": {
        "base": "enabled",
        "themes/dark": "enabled"
      }
    }
  ],
  "$metadata": {
    "tokenSetOrder": [
      "base",
      "themes/2",
      "themes/dark"
    ],
    "activeThemes": [
      "dfw/default"
    ],
    "activeSets": [
      "base"
    ]
  }
}

